# frozen_string_literal: true

# FS-B127 to FS-B130: RBS for user classes.
require 'open3'
require 'tmpdir'

RSpec.describe FieldStruct::RBS do
  let(:header) do
    <<~TEXT
      # Generated by FieldStruct::RBS. Types describe a valid instance: an
      # invalid one (a required field left unset, or a :keep_raw coercion
      # failure holding the raw input) can hold other values. Check valid?.
    TEXT
  end

  def field_of(type, **options)
    klass = Class.new(FieldStruct::Base)
    klass.field(:probe, type, **options)
    klass.metadata[:probe]
  end

  describe '.generate' do
    it 'writes the header, the class and one reader/writer pair per field' do
      stub_const('Plant', Class.new(FieldStruct::Base) do
        required :species, :string
        optional :leaves, :integer
      end)

      expect(described_class.generate(Plant)).to eq(<<~RBS)
        #{header}class Plant < ::FieldStruct::Base
          attr_reader species: ::String
          def species=: (::String? value) -> ::String?

          attr_reader leaves: ::Integer?
          def leaves=: (::Integer? value) -> ::Integer?
        end
      RBS
    end

    it 'wraps the class in modules mirroring its namespace and indents by level' do
      stub_const('Nursery', Module.new)
      stub_const('Nursery::Inventory', Module.new)
      stub_const('Nursery::Inventory::Seedling', Class.new(FieldStruct::Base) { required :sku, :string })

      expect(described_class.generate(Nursery::Inventory::Seedling)).to eq(<<~RBS)
        #{header}module Nursery
          module Inventory
            class Seedling < ::FieldStruct::Base
              attr_reader sku: ::String
              def sku=: (::String? value) -> ::String?
            end
          end
        end
      RBS
    end

    it 'uses class for a namespace that is a class' do
      stub_const('Garden', Class.new)
      stub_const('Garden::Entry', Class.new(FieldStruct::Base))

      expect(described_class.generate(Garden::Entry)).to include("class Garden\n  class Entry < ::FieldStruct::Base\n  end\nend")
    end

    it 'skips fields inherited unchanged and keeps redeclared ones' do
      stub_const('Parent', Class.new(FieldStruct::Base) do
        required :id, :integer
        optional :note, :string
      end)
      stub_const('Child', Class.new(Parent) do
        required :note, :string
        optional :extra, :symbol
      end)

      out = described_class.generate(Child)
      expect(out).to include('class Child < ::Parent')
      expect(out).to include('attr_reader note: ::String', 'attr_reader extra: ::Symbol?')
      expect(out).not_to include('attr_reader id')
    end

    it 'emits an empty class when the class declares nothing' do
      stub_const('Empty', Class.new(FieldStruct::Base))
      expect(described_class.generate(Empty)).to eq("#{header}class Empty < ::FieldStruct::Base\nend\n")
    end

    it 'refuses what is not a Base subclass' do
      [String, FieldStruct::Base, 3].each do |bad|
        expect do
          described_class.generate(bad)
        end.to raise_error(ArgumentError,
                           "FieldStruct::RBS.generate expects a FieldStruct::Base subclass, got #{bad.inspect}")
      end
    end

    it 'refuses an anonymous class' do
      expect do
        described_class.generate(Class.new(FieldStruct::Base))
      end.to raise_error(ArgumentError, 'cannot generate RBS for an anonymous class')
    end
  end

  describe '.type_for' do
    it 'refuses a non-Field' do
      expect do
        described_class.type_for(:name)
      end.to raise_error(ArgumentError,
                         'FieldStruct::RBS.type_for expects a FieldStruct::Field (e.g. User.metadata[:name]), got :name')
    end

    it 'is nullable unless required by default, and honours nullable:' do
      optional = field_of(:string)
      required = field_of(:string, required: true)
      expect(described_class.type_for(optional)).to eq('::String?')
      expect(described_class.type_for(required)).to eq('::String')
      expect(described_class.type_for(required, nullable: true)).to eq('::String?')
      expect(described_class.type_for(optional, nullable: false)).to eq('::String')
    end

    {
      string: '::String', immutable_string: '::String', uuid: '::String', url: '::String', email: '::String', binary: '::String',
      symbol: '::Symbol', integer: '::Integer', float: '::Float', decimal: '::BigDecimal', big_decimal: '::BigDecimal',
      boolean: 'bool', date: '::Date', time: '::Time', datetime: '::DateTime'
    }.each do |type, expected|
      it "derives #{expected} for :#{type}" do
        expect(described_class.type_for(field_of(type, required: true))).to eq(expected)
      end
    end

    it 'derives untyped for :value, never untyped?' do
      expect(described_class.type_for(field_of(:value))).to eq('untyped')
      expect(described_class.type_for(field_of(:value), nullable: true)).to eq('untyped')
    end

    it 'derives booleans as bool?' do
      expect(described_class.type_for(field_of(:boolean))).to eq('bool?')
    end

    it 'names nested structs fully qualified' do
      stub_const('Nursery', Module.new)
      stub_const('Nursery::Bed', Class.new(FieldStruct::Base))
      expect(described_class.type_for(field_of(Nursery::Bed, required: true))).to eq('::Nursery::Bed')
    end

    it 'refuses to name an anonymous nested class' do
      anonymous = Class.new(FieldStruct::Base)
      expect do
        described_class.type_for(field_of(anonymous))
      end.to raise_error(ArgumentError,
                         'FieldStruct::RBS cannot name an anonymous class; assign it to a constant')
    end

    it 'makes scalar array elements nullable and nested elements not' do
      stub_const('LineItem', Class.new(FieldStruct::Base))
      expect(described_class.type_for(field_of(:array, of: :string, required: true))).to eq('::Array[::String?]')
      expect(described_class.type_for(field_of(:array, of: :boolean, required: true))).to eq('::Array[bool?]')
      expect(described_class.type_for(field_of(:array, of: LineItem, required: true))).to eq('::Array[::LineItem]')
      expect(described_class.type_for(field_of(:array, of: :array, required: true))).to eq('::Array[::Array[untyped]?]')
      expect(described_class.type_for(field_of(:array, of: :value, required: true))).to eq('::Array[untyped]')
    end

    it 'derives a union from its members, de-duplicated' do
      expect(described_class.type_for(field_of(:union, of: %i[integer string], required: true))).to eq('(::Integer | ::String)')
      expect(described_class.type_for(field_of(:union, of: %i[string uuid], required: true))).to eq('::String')
      expect(described_class.type_for(field_of(:union, of: %i[integer string]))).to eq('(::Integer | ::String)?')
      expect(described_class.type_for(field_of(:union, of: %i[integer value], required: true))).to eq('untyped')
    end

    it 'uses the field override, then the type override, before deriving' do
      expect(described_class.type_for(field_of(:string, rbs_type: '::Pathname', required: true))).to eq('::Pathname')
      expect(described_class.type_for(field_of(:string, rbs_type: '::Pathname'))).to eq('::Pathname?')
      expect(described_class.type_for(field_of(:string, rbs_type: '::Pathname?'))).to eq('::Pathname?')
      expect(described_class.type_for(field_of(:string, rbs_type: 'untyped'))).to eq('untyped')
    end

    it 'strips an override and parenthesizes operators unless already one group' do
      expect(described_class.type_for(field_of(:string, rbs_type: '  ::A | ::B  ', required: true))).to eq('(::A | ::B)')
      expect(described_class.type_for(field_of(:string, rbs_type: '::A & ::B'))).to eq('(::A & ::B)?')
      expect(described_class.type_for(field_of(:string, rbs_type: '(::A | ::B)', required: true))).to eq('(::A | ::B)')
      expect(described_class.type_for(field_of(:string, rbs_type: '(::A | ::B)?', required: true))).to eq('(::A | ::B)?')
      expect(described_class.type_for(field_of(:string, rbs_type: '(::A) | (::B)', required: true))).to eq('((::A) | (::B))')
    end

    describe 'custom types' do
      def custom(ruby_type, rbs: nil)
        Class.new(FieldStruct::Types::Base) do
          define_method(:coerce) { |value, **| value }
          define_method(:ruby_type) { ruby_type }
          define_method(:rbs_type) { rbs }
        end
      end

      it 'maps bare generics, Object, and multiple classes' do
        expect(described_class.type_for(field_of(custom(Array), required: true))).to eq('::Array[untyped]')
        expect(described_class.type_for(field_of(custom(Hash), required: true))).to eq('::Hash[untyped, untyped]')
        expect(described_class.type_for(field_of(custom(Range), required: true))).to eq('::Range[untyped]')
        expect(described_class.type_for(field_of(custom(Object), required: true))).to eq('untyped')
        expect(described_class.type_for(field_of(custom([Integer, String]), required: true))).to eq('(::Integer | ::String)')
        expect(described_class.type_for(field_of(custom([TrueClass, FalseClass]), required: true))).to eq('bool')
        expect(described_class.type_for(field_of(custom(Pathname), required: true))).to eq('::Pathname')
      end

      it 'prefers the type instance rbs_type hook' do
        expect(described_class.type_for(field_of(custom(Object, rbs: '::Money'), required: true))).to eq('::Money')
      end
    end
  end

  describe 'FS-B130: validity under rbs' do
    it 'validates for a sample hierarchy next to the gem signature' do
      stub_const('Nursery', Module.new)
      stub_const('Nursery::Bed', Class.new(FieldStruct::Base) { required :habitat, :string })
      stub_const('Nursery::Planting', Class.new(FieldStruct::Base) do
        required :id, :integer
        optional :ship_to, Nursery::Bed
        optional :lines, :array, of: Nursery::Bed
        optional :tags, :array, of: :string
        optional :paid, :boolean
        optional :ref, :union, of: %i[integer string]
        optional :extra, :value
        optional :weight, :decimal, rbs_type: '::BigDecimal | ::Integer'
      end)
      stub_const('Nursery::Rush', Class.new(Nursery::Planting) { required :deadline, :datetime })

      Dir.mktmpdir do |dir|
        source = %w[Bed Planting Rush].map { |name| described_class.generate(Nursery.const_get(name)) }.join("\n")
        File.write(File.join(dir, 'models.rbs'), source)
        sig = FieldStruct.root.join('sig').to_s
        libraries = %w[date time bigdecimal pathname pp].flat_map { |name| ['-r', name] }
        output, status = Open3.capture2e('bundle', 'exec', 'rbs', '--no-collection', *libraries, '-I', sig, '-I', dir, 'validate',
                                         chdir: FieldStruct.root.to_s)
        expect(status).to be_success, output
      end
    end
  end
end
